WITH web_events_by_session AS (SELECT session_id, COUNT(*) AS row_count, MIN(duration_sec) AS min_duration_sec FROM web_events GROUP BY session_id) SELECT sessions.id, sessions.started_at, web_events_by_session.row_count, web_events_by_session.min_duration_sec FROM sessions INNER JOIN web_events_by_session ON sessions.id = web_events_by_session.session_id WHERE web_events_by_session.row_count >= 3
